def get_layer_number(grid, region_start_r, region_start_c, region_end_r, region_end_c):
    """For demo2, return the layer number (0=outermost ring) for each pixel in region"""
    layers = {}
    visited = set()

    # BFS from outside in
    queue = []

    # Add boundary pixels
    for r in range(region_start_r, region_end_r+1):
        for c in range(region_start_c, region_end_c+1):
            if r == region_start_r or r == region_end_r or c == region_start_c or c == region_end_c:
                key = (r, c)
                if key not in visited:
                    visited.add(key)
                    queue.append((key, 0))  # layer 0 = outermost

    while queue:
        (r, c), layer = queue.pop(0)
        val = grid[r][c]

        # Check neighbors
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if region_start_r <= nr <= region_end_r and region_start_c <= nc <= region_end_c:
                key = (nr, nc)
                if key not in visited and grid[nr][nc] == val:
                    visited.add(key)
                    queue.append((key, layer + 1))

    return {key: layer for key, layer in layers.items()}

