def construct_transformed_grid():
    """Construct solution by analyzing and applying transformations"""

    test = [[x for x in row] for row in demo_input_3]
    result = [[0]*max(len(row) for row in demo_input_3) for _ in range(len(demo_input_3))]

    # Process each rectangle independently - find colors present and their order
    # then reverse that sequence

    n_rows = len(test)
    max_cols = max(len(row) for row in test)

    # Find unique non-zero regions and process each
    regions = []
    visited = [[False]*max_cols for _ in range(n_rows)]

    for r in range(n_rows):
        for c in range(max_cols):
            if c >= len(test[r]) or visited[r][c] or test[r][c] == 0:
                continue

            # Get bounding box of this connected region
            color = test[r][c]
            cells = []
            queue = [(r, c)]
            visited[r][c] = True

            while queue:
                cr, cc = queue.pop(0)
                cells.append((cr, cc))
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = cr+dr, cc+dc
                    if 0 <= nr < n_rows and 0 <= nc < max_cols:
                        if not visited[nr][nc] and nc < len(test[nr]) and test[nr][nc] == color:
                            visited[nr][nc] = True
                            queue.append((nr, nc))

            min_r, max_r = min(x[0] for x in cells), max(x[0] for x in cells)
            min_c, max_c = min(x[1] for x in cells), max(x[1] for x in cells)

            # Calculate layer assignment for cells in this region
            # Layer 0 = border, higher = interior
            cell_layers = {}
            for rr, cc in cells:
                dist = min(rr-min_r, max_r-rr, cc-min_c, max_c-cc)
                cell_layers[(rr, cc)] = dist

            # Group cells by layer and collect unique colors at each layer
            layers_by_depth = {}
            for (rr, cc), depth in cell_layers.items():
                orig_color = test[rr][cc]
                if depth not in layers_by_depth:
                    layers_by_depth[depth] = set()
                layers_by_depth[depth].add(orig_color)

            sorted_depths = sorted(layers_by_depth.keys())

            # Collect representative color at each depth
            color_by_depth = {d: list(layers_by_depth[d])[0] for d in sorted_depths}

            print(f"Region [{min_r},{min_c}]-{[max_r,max_c]}: depths={sorted_depths}, colors={color_by_depth}")

            # Reverse: deepest layer's color goes to outermost, etc.
            reversed_colors = {d: color_by_depth[max(sorted_depths)-d] for d in sorted_depths}

            # Apply transformation
            for (rr, cc), depth in cell_layers.items():
                new_color = reversed_colors[depth]
                result[rr][cc] = new_color

    return result

